={{ (() => {
  // 2xx = chave aceita; 401/403 = chave recusada; qualquer outra coisa (5xx, 429, rede, timeout) não permite concluir
  const code = $json.statusCode ?? 0
  if (code >= 200 && code < 300) return 'VALIDA'
  if (code === 401 || code === 403) return 'INVALIDA'
  return 'INDETERMINADA'
})() }}

={{ (() => {
  // INDETERMINADA não muda o status: mantém o último resultado conclusivo da fonte
  const code = $json.statusCode ?? 0
  if (code >= 200 && code < 300) return 'VALIDA'
  if (code === 401 || code === 403) return 'INVALIDA'
  return $('Ler fontes ativas').item.json.status || 'PENDENTE'
})() }}

={{ (() => {
  const code = $json.statusCode ?? 0
  // Item veio da saída 'não suportado' do Switch: não houve chamada HTTP
  if (!$json.statusCode && !$json.error) return 'tipoAuth não suportado: ' + $('Ler fontes ativas').item.json.tipoAuth
  // Rede, timeout ou credencial ausente no nó
  if ($json.error) return ('Falha na chamada: ' + ($json.error.message || JSON.stringify($json.error))).slice(0, 250)
  if (code >= 200 && code < 300) return 'OK'
  return ('HTTP ' + code + ': ' + ($json.body?.error?.message || $json.body?.message || 'sem detalhe')).slice(0, 250)
})() }}

